// ==================================================
// Evidence Analysis Context Builder
//
// Builds a constrained evidence-based analysis
// context from validated canonical inputs.
// ==================================================

const input = $json;

const initialAnalysis =
  input.initial_analysis;

const investigationPlan =
  input.investigation_plan;

const investigationEvidence =
  input.investigation_evidence;


// --------------------------------------------------
// 1. Validate input consistency
// --------------------------------------------------

if (
  !initialAnalysis ||
  !investigationPlan ||
  !investigationEvidence
) {
  throw new Error(
    "Evidence Analysis Context Builder requires initial_analysis, investigation_plan and investigation_evidence"
  );
}


const alertIds = [
  initialAnalysis.alert_id,
  investigationPlan.alert_id,
  investigationEvidence.alert_id
];


if (
  alertIds.some(
    value =>
      typeof value !== "string" ||
      value.trim() === ""
  )
) {
  throw new Error(
    "All evidence analysis inputs require alert_id"
  );
}


if (
  new Set(alertIds).size !== 1
) {
  throw new Error(
    "alert_id mismatch between evidence analysis inputs"
  );
}


// --------------------------------------------------
// 2. Build immutable context
// --------------------------------------------------

const context = {

  context_version:
    "1.0",

  task:
    "evidence_based_investigation_assessment",

  alert_id:
    initialAnalysis.alert_id,

  instructions: {

    objective:
      "Reassess the incident using validated investigation evidence.",

    evidence_policy: [
      "Treat validated tool evidence as observed facts only when explicitly represented.",
      "Do not invent events, entities, relationships, threat intelligence, intent, or causality.",
      "Do not classify a process as malicious solely because of its executable name.",
      "Do not interpret PowerShell usage as malicious without supporting evidence.",
      "Do not infer that two events are causally related merely because they are temporally close.",
      "Correlations must cite the evidence sources that support them.",
      "Keep observations, correlations, hypotheses, and conclusions separate.",
      "The verdict must reflect the available evidence, including uncertainty.",
      "Do not perform or recommend destructive actions unless evidence clearly supports escalation."
    ]
  },


  preliminary_analysis: {
    summary:
      initialAnalysis.summary,

    verdict:
      initialAnalysis.preliminary_verdict,

    confidence:
      initialAnalysis.confidence,

    missing_evidence:
      initialAnalysis.missing_evidence || []
  },


  investigation_plan: {
    objective:
      investigationPlan.objective,

    steps:
      investigationPlan.investigation_steps || []
  },


  investigation_evidence: {
    status:
      investigationEvidence.status,

    execution_summary:
      investigationEvidence.execution_summary,

    tool_executions:
      investigationEvidence.tool_executions || []
  }
};


// --------------------------------------------------
// 3. Return constrained context
// --------------------------------------------------

return [
  {
    json:
      context
  }
];

// ==================================================
// Evidence Analysis Request Builder
//
// Builds the first evidence-based investigation
// assessment request.
//
// Security properties:
// - evidence is authoritative only for exact fields
// - relationships are not inferred from proximity
// - observed facts are separated from hypotheses
// - no authorization/legitimacy assumptions
// - no generic repeat-investigation gaps
//
// The LLM output is untrusted and must later pass
// Evidence Analysis Validator.
// ==================================================

const context = $json;


// --------------------------------------------------
// 1. Validate investigation context
// --------------------------------------------------

if (
  !context ||
  typeof context !== "object" ||
  Array.isArray(context)
) {
  throw new Error(
    "Evidence Analysis Request Builder requires a valid investigation context"
  );
}


if (
  typeof context.alert_id !== "string" ||
  context.alert_id.trim() === ""
) {
  throw new Error(
    "Evidence Analysis Request Builder requires alert_id"
  );
}


if (
  !context.investigation_evidence ||
  typeof context.investigation_evidence !== "object" ||
  Array.isArray(context.investigation_evidence)
) {
  throw new Error(
    "Evidence Analysis Request Builder requires investigation_evidence"
  );
}


if (
  !Array.isArray(
    context.investigation_evidence.tool_executions
  )
) {
  throw new Error(
    "Evidence Analysis Request Builder requires investigation_evidence.tool_executions"
  );
}


// --------------------------------------------------
// 2. Expected output structure
// --------------------------------------------------

const expectedOutput = {

  assessment_version:
    "1.0",

  alert_id:
    context.alert_id,

  summary:
    "Concise evidence-based incident assessment.",

  observed_evidence: [
    {
      source:
        "get_signins",

      field:
        "source_ip",

      value:
        "example"
    }
  ],

  correlations: [
    {
      description:
        "Relationship supported by validated evidence.",

      evidence_sources: [
        "get_signins"
      ]
    }
  ],

  hypotheses:
    [],

  risk_assessment: {

    level:
      "unknown",

    reasoning:
      []
  },

  verdict:
    "inconclusive",

  confidence:
    0,

  remaining_gaps:
    [],

  recommended_next_actions:
    []
};


// --------------------------------------------------
// 3. System prompt
// --------------------------------------------------

const systemPrompt =
  "You are performing an evidence-based cybersecurity incident assessment. " +

  "Treat all supplied tool evidence as authoritative only for the exact fields explicitly represented in the evidence. " +

  "Do not invent events, entities, relationships, causality, authorization, user intent, attacker intent, compromise, travel, device ownership, threat intelligence, or missing telemetry. " +

  "Keep observed evidence, correlations, hypotheses, risk assessment, verdict, remaining gaps, and recommended actions conceptually separate. " +

  "An observation is a fact explicitly represented in tool evidence. " +

  "A correlation is a relationship supported by explicit shared entities, timestamps, or other validated evidence. " +

  "Temporal proximity alone does not establish causality. " +

  "A hypothesis must remain explicitly uncertain and must not be presented as an observed fact. " +

  "Do not describe authentication or endpoint activity as legitimate, authorized, benign, user-confirmed, attacker-controlled, compromised, or malicious unless validated evidence explicitly establishes that state. " +

  "Successful authentication means only that the authentication succeeded. " +

  "MFA means only that MFA was satisfied or used as represented by the evidence. " +

  "Successful MFA does not establish that the legitimate user authorized the authentication. " +

  "Do not classify PowerShell execution as malicious solely because PowerShell was executed. " +

  "Do not classify a browser network connection as malicious or legitimate without supporting evidence. " +

  "Do not create generic remaining gaps that merely request repeating evidence collection already completed successfully. " +

  "Remaining gaps must describe a specific missing fact or explicit missing investigation scope that could materially change the assessment. " +

  "Return only valid JSON without Markdown or explanatory text outside the JSON object.";


// --------------------------------------------------
// 4. User prompt
// --------------------------------------------------

const userPrompt =
  "Analyze the supplied validated investigation evidence and produce one evidence-based assessment. " +

  "Return exactly one JSON object matching this structure: " +
  JSON.stringify(expectedOutput) +
  ". " +

  "MANDATORY RULES: " +

  "1. assessment_version must be exactly '1.0'. " +

  "2. alert_id must exactly match the supplied alert_id. " +

  "3. observed_evidence must contain only facts explicitly represented in investigation_evidence.tool_executions[].evidence. " +

  "4. Every observed_evidence source must exactly identify the tool that produced that evidence. " +

  "5. Every observed_evidence field must exactly match a field or nested field path represented in that tool evidence. " +

  "6. Preserve exact evidence values and JSON types. Strings remain strings, numbers remain numbers, objects remain objects, arrays remain arrays and null remains null. " +

  "7. Never transform an evidence VALUE into a FIELD name. For example, if event_type is 'network_connection', use field='event_type' and value='network_connection'. Never use field='network_connection'. " +

  "8. Do not invent geographic relationships between IP addresses and locations unless the same authoritative event explicitly establishes that relationship. " +

  "9. Do not infer account compromise solely from different observed locations or IP addresses. " +

  "10. Do not infer impossible travel unless evidence explicitly supports the required user, timestamps and geographic relationship. " +

  "11. The endpoint network_connection at 2026-08-23T17:39:00Z occurs before the sign-in at 2026-08-23T17:42:00Z. Do not reverse this ordering. " +

  "12. Temporal proximity between endpoint and authentication events does not establish causality. " +

  "13. PowerShell execution must not be classified as malicious solely because powershell.exe was executed. " +

  "14. The command 'powershell.exe -NoProfile -Command Get-Process' must not by itself be treated as proof of malicious behavior. " +

  "15. The msedge.exe connection to 20.190.128.25:443 must not be described as malicious, benign, legitimate or authorized without additional supporting evidence. " +

  "16. Do not describe either sign-in as legitimate or authorized merely because status='success' or authentication_method='MFA'. " +

  "17. Successful MFA establishes an observed authentication property only. It does not prove that the legitimate account owner performed or authorized the sign-in. " +

  "18. Do not describe endpoint events as legitimate user activity unless validated evidence explicitly establishes legitimacy or authorization. " +

  "19. risk_assessment.level must be exactly one of: low, medium, high, critical, unknown. " +

  "20. verdict must be exactly one of: benign, suspicious, malicious, inconclusive. " +

  "21. malicious requires strong positive evidence of malicious or unauthorized activity. " +

  "22. benign requires affirmative evidence supporting benign or authorized activity. Absence of malicious evidence alone is insufficient. " +

  "23. suspicious may be used when meaningful risk indicators exist but compromise is not established. " +

  "24. inconclusive is appropriate when available evidence cannot support a stronger classification. " +

  "25. confidence must be a number between 0 and 1. " +

  "26. remaining_gaps must be an array of strings only. " +

  "27. Every remaining gap must describe a specific missing fact or explicitly missing investigation scope that could materially change the assessment. " +

  "28. Do not create generic gaps such as 'additional endpoint activity', 'more endpoint activity', 'additional sign-in activity', 'more sign-in activity', 'further investigation', or similar generic requests. " +

  "29. get_signins evidence has already been collected. Do not request generic sign-in collection again. " +

  "30. If additional sign-in history is genuinely required, a remaining gap must identify the specific missing scope. Do not invent a new time range. " +

  "31. get_endpoint_activity evidence has already been collected. Do not request generic endpoint activity again. " +

  "32. Do not create 'Additional endpoint activity beyond the collected events.' or semantically equivalent generic gaps. " +

  "33. Additional endpoint collection may only be identified as a remaining gap when an explicit new time range, host, event type, telemetry source, or other authoritative investigation scope is supplied in the context. Never invent that scope. " +

  "34. Do not create a remaining gap asking to determine whether PowerShell was legitimate or malicious merely because PowerShell appears in evidence. " +

  "35. Do not create a remaining gap asking to investigate 20.190.128.25 merely because it appears as a destination IP. " +

  "36. Evidence existence does not itself create authorization for another investigation step. " +

  "37. recommended_next_actions must not simply repeat already-completed get_signins or get_endpoint_activity collection. " +

  "38. recommended_next_actions must correspond to legitimate unresolved evidence requirements actually represented in remaining_gaps. " +

  "39. If the evidence does not establish a specific materially relevant missing fact, remaining_gaps may be empty. " +

  "40. If remaining_gaps is empty, recommended_next_actions should normally also be empty. " +

  "41. Do not manufacture gaps merely to avoid returning an inconclusive verdict. " +

  "COMPLETE VALIDATED INVESTIGATION CONTEXT: " +
  JSON.stringify(context);


// --------------------------------------------------
// 5. Build Ollama request
// --------------------------------------------------

return [
  {
    json: {

      model:
        "qwen3:8b",

      messages: [
        {
          role:
            "system",

          content:
            systemPrompt
        },

        {
          role:
            "user",

          content:
            userPrompt
        }
      ],

      stream:
        false,

      think:
        false,

      keep_alive:
        "5m",

      format:
        "json"
    }
  }
];

// ==================================================
// Evidence Analysis Validator
//
// Validates the evidence-based assessment produced
// by the LLM.
//
// Validation covers:
// - JSON structure
// - alert_id consistency
// - enum values
// - confidence
// - observed evidence provenance
// - tool source validation
// - exact evidence value matching
// - duplicate completed investigations in gaps
//
// LLM output is treated as untrusted input.
// ==================================================


// --------------------------------------------------
// 1. Extract Ollama response
// --------------------------------------------------

const response = $json;

const content =
  response?.message?.content;

if (
  !content ||
  typeof content !== "string"
) {
  throw new Error(
    "Evidence analysis validation failed: message.content is missing or empty"
  );
}


// --------------------------------------------------
// 2. Parse JSON
// --------------------------------------------------

let assessment;

try {

  assessment =
    JSON.parse(content);

} catch (error) {

  throw new Error(
    `Evidence analysis validation failed: response is not valid JSON: ${error.message}`
  );
}


// --------------------------------------------------
// 3. Retrieve canonical context
// --------------------------------------------------

const context =
  $("Evidence Analysis Context Builder").first().json;


if (
  !context ||
  typeof context !== "object"
) {
  throw new Error(
    "Evidence analysis validation failed: canonical investigation context is unavailable"
  );
}


// --------------------------------------------------
// 4. Errors
// --------------------------------------------------

const errors = [];


// --------------------------------------------------
// 5. Helpers
// --------------------------------------------------

function requireString(
  field,
  value
) {

  if (
    typeof value !== "string" ||
    value.trim() === ""
  ) {
    errors.push(
      `${field} must be a non-empty string`
    );
  }
}


function requireArray(
  field,
  value
) {

  if (
    !Array.isArray(value)
  ) {
    errors.push(
      `${field} must be an array`
    );
  }
}


function validateStringArray(
  field,
  value
) {

  if (
    !Array.isArray(value)
  ) {

    errors.push(
      `${field} must be an array`
    );

    return;
  }


  value.forEach(
    (item, index) => {

      if (
        typeof item !== "string" ||
        item.trim() === ""
      ) {
        errors.push(
          `${field}[${index}] must be a non-empty string`
        );
      }
    }
  );
}


// --------------------------------------------------
// Deep equality
//
// Important:
// - preserves JSON types
// - object key order does NOT matter
// - array element order DOES matter
// - nested objects are compared recursively
// --------------------------------------------------

function deepEqual(
  valueA,
  valueB
) {

  // Exact primitive equality, including null.
  if (
    valueA === valueB
  ) {
    return true;
  }


  // Different null/undefined states.
  if (
    valueA === null ||
    valueB === null ||
    valueA === undefined ||
    valueB === undefined
  ) {
    return false;
  }


  // Exact JSON type must match.
  if (
    typeof valueA !==
      typeof valueB
  ) {
    return false;
  }


  // Arrays.
  if (
    Array.isArray(valueA) ||
    Array.isArray(valueB)
  ) {

    if (
      !Array.isArray(valueA) ||
      !Array.isArray(valueB)
    ) {
      return false;
    }


    if (
      valueA.length !==
        valueB.length
    ) {
      return false;
    }


    for (
      let index = 0;
      index < valueA.length;
      index++
    ) {

      if (
        !deepEqual(
          valueA[index],
          valueB[index]
        )
      ) {
        return false;
      }
    }


    return true;
  }


  // Objects.
  if (
    typeof valueA === "object"
  ) {

    const keysA =
      Object.keys(valueA)
        .sort();

    const keysB =
      Object.keys(valueB)
        .sort();


    if (
      keysA.length !==
        keysB.length
    ) {
      return false;
    }


    for (
      let index = 0;
      index < keysA.length;
      index++
    ) {

      if (
        keysA[index] !==
          keysB[index]
      ) {
        return false;
      }
    }


    for (
      const key
      of keysA
    ) {

      if (
        !deepEqual(
          valueA[key],
          valueB[key]
        )
      ) {
        return false;
      }
    }


    return true;
  }


  // Remaining primitive values differ.
  return false;
}


// --------------------------------------------------
// 6. Build authoritative evidence index
// --------------------------------------------------

const evidenceIndex =
  new Map();


const validToolSources =
  new Set();


function addEvidence(
  source,
  field,
  value
) {

  const key =
    `${source}::${field}`;

  if (
    !evidenceIndex.has(key)
  ) {
    evidenceIndex.set(
      key,
      []
    );
  }

  evidenceIndex
    .get(key)
    .push(value);
}


// --------------------------------------------------
// 7. Flatten evidence recursively
// --------------------------------------------------

function flattenEvidence(
  source,
  value,
  prefix = ""
) {

  if (
    value === null ||
    value === undefined
  ) {

    if (prefix) {
      addEvidence(
        source,
        prefix,
        value
      );
    }

    return;
  }


  // Arrays are preserved as complete values.
  if (
    Array.isArray(value)
  ) {

    if (prefix) {
      addEvidence(
        source,
        prefix,
        value
      );
    }

    return;
  }


  // Objects are preserved as complete values
  // AND recursively flattened.
  if (
    typeof value === "object"
  ) {

    if (prefix) {
      addEvidence(
        source,
        prefix,
        value
      );
    }


    for (
      const [key, childValue]
      of Object.entries(value)
    ) {

      const childPrefix =
        prefix
          ? `${prefix}.${key}`
          : key;

      flattenEvidence(
        source,
        childValue,
        childPrefix
      );
    }

    return;
  }


  // Primitive value.
  if (prefix) {

    addEvidence(
      source,
      prefix,
      value
    );
  }
}


// --------------------------------------------------
// 8. Index tool evidence
// --------------------------------------------------

const toolExecutions =
  context
    ?.investigation_evidence
    ?.tool_executions || [];


for (
  const execution
  of toolExecutions
) {

  const tool =
    execution?.tool;


  if (
    typeof tool !== "string" ||
    tool.trim() === ""
  ) {
    continue;
  }


  validToolSources.add(tool);


  if (
    !Array.isArray(
      execution.evidence
    )
  ) {
    continue;
  }


  for (
    const event
    of execution.evidence
  ) {

    if (
      !event ||
      typeof event !== "object" ||
      Array.isArray(event)
    ) {
      continue;
    }


    for (
      const [field, value]
      of Object.entries(event)
    ) {

      flattenEvidence(
        tool,
        value,
        field
      );
    }
  }
}


// --------------------------------------------------
// 9. Top-level structure
// --------------------------------------------------

if (
  !assessment ||
  typeof assessment !== "object" ||
  Array.isArray(assessment)
) {

  errors.push(
    "assessment must be a JSON object"
  );

} else {

  if (
    assessment.assessment_version !== "1.0"
  ) {
    errors.push(
      "assessment_version must be '1.0'"
    );
  }


  requireString(
    "alert_id",
    assessment.alert_id
  );


  if (
    assessment.alert_id !==
      context.alert_id
  ) {
    errors.push(
      "alert_id does not match the canonical investigation context"
    );
  }


  requireString(
    "summary",
    assessment.summary
  );


  requireArray(
    "observed_evidence",
    assessment.observed_evidence
  );


  requireArray(
    "correlations",
    assessment.correlations
  );


  validateStringArray(
    "hypotheses",
    assessment.hypotheses
  );


  validateStringArray(
    "remaining_gaps",
    assessment.remaining_gaps
  );


  validateStringArray(
    "recommended_next_actions",
    assessment.recommended_next_actions
  );
}


// --------------------------------------------------
// 10. Validate observed evidence
// --------------------------------------------------

if (
  Array.isArray(
    assessment.observed_evidence
  )
) {

  assessment.observed_evidence.forEach(
    (evidence, index) => {

      const prefix =
        `observed_evidence[${index}]`;


      if (
        !evidence ||
        typeof evidence !== "object" ||
        Array.isArray(evidence)
      ) {

        errors.push(
          `${prefix} must be an object`
        );

        return;
      }


      requireString(
        `${prefix}.source`,
        evidence.source
      );


      requireString(
        `${prefix}.field`,
        evidence.field
      );


      // ------------------------------------------
      // Source must be an executed tool
      // ------------------------------------------

      if (
        typeof evidence.source === "string" &&
        !validToolSources.has(
          evidence.source
        )
      ) {

        errors.push(
          `${prefix}.source '${evidence.source}' is not a validated tool evidence source`
        );
      }


      // ------------------------------------------
      // Evidence must exist exactly in tool output
      // ------------------------------------------

      if (
        typeof evidence.source === "string" &&
        typeof evidence.field === "string"
      ) {

        const key =
          `${evidence.source}::${evidence.field}`;


        if (
          !evidenceIndex.has(key)
        ) {

          errors.push(
            `${prefix}: field '${evidence.field}' does not exist in evidence produced by '${evidence.source}'`
          );

        } else {

          const authoritativeValues =
            evidenceIndex.get(key);


          const exactMatch =
            authoritativeValues.some(
              value =>
                deepEqual(
                  value,
                  evidence.value
                )
            );


          if (!exactMatch) {

            errors.push(
              `${prefix}: value does not exactly match evidence produced by '${evidence.source}' for field '${evidence.field}'`
            );
          }
        }
      }
    }
  );
}


// --------------------------------------------------
// 11. Correlations
// --------------------------------------------------

if (
  Array.isArray(
    assessment.correlations
  )
) {

  assessment.correlations.forEach(
    (correlation, index) => {

      const prefix =
        `correlations[${index}]`;


      if (
        !correlation ||
        typeof correlation !== "object" ||
        Array.isArray(correlation)
      ) {

        errors.push(
          `${prefix} must be an object`
        );

        return;
      }


      requireString(
        `${prefix}.description`,
        correlation.description
      );


      if (
        !Array.isArray(
          correlation.evidence_sources
        ) ||
        correlation.evidence_sources.length === 0
      ) {

        errors.push(
          `${prefix}.evidence_sources must contain at least one source`
        );

      } else {

        correlation.evidence_sources.forEach(
          (source, sourceIndex) => {

            if (
              typeof source !== "string" ||
              source.trim() === ""
            ) {

              errors.push(
                `${prefix}.evidence_sources[${sourceIndex}] must be a non-empty string`
              );

              return;
            }


            if (
              !validToolSources.has(source)
            ) {

              errors.push(
                `${prefix}.evidence_sources[${sourceIndex}] '${source}' is not a validated tool evidence source`
              );
            }
          }
        );
      }
    }
  );
}


// --------------------------------------------------
// 12. Risk assessment
// --------------------------------------------------

const validRiskLevels = [
  "low",
  "medium",
  "high",
  "critical",
  "unknown"
];


if (
  !assessment.risk_assessment ||
  typeof assessment.risk_assessment !== "object" ||
  Array.isArray(
    assessment.risk_assessment
  )
) {

  errors.push(
    "risk_assessment must be an object"
  );

} else {

  if (
    !validRiskLevels.includes(
      assessment.risk_assessment.level
    )
  ) {

    errors.push(
      "risk_assessment.level contains an invalid value"
    );
  }


  validateStringArray(
    "risk_assessment.reasoning",
    assessment.risk_assessment.reasoning
  );
}


// --------------------------------------------------
// 13. Verdict
// --------------------------------------------------

const validVerdicts = [
  "benign",
  "suspicious",
  "malicious",
  "inconclusive"
];


if (
  !validVerdicts.includes(
    assessment.verdict
  )
) {

  errors.push(
    "verdict contains an invalid value"
  );
}


// --------------------------------------------------
// 14. Confidence
// --------------------------------------------------

if (
  typeof assessment.confidence !== "number" ||
  Number.isNaN(
    assessment.confidence
  ) ||
  assessment.confidence < 0 ||
  assessment.confidence > 1
) {

  errors.push(
    "confidence must be a number between 0 and 1"
  );
}


// --------------------------------------------------
// 15. Detect already-completed generic gaps
// --------------------------------------------------

const completedTools =
  new Set(
    toolExecutions
      .filter(
        execution =>
          execution?.status === "success"
      )
      .map(
        execution =>
          execution.tool
      )
  );


const forbiddenGapPatterns = [];


if (
  completedTools.has(
    "get_signins"
  )
) {

  forbiddenGapPatterns.push(
    "historical sign-in activity",
    "historical signin activity",
    "collect historical sign-in data",
    "collect sign-in activity"
  );
}


if (
  completedTools.has(
    "get_endpoint_activity"
  )
) {

  forbiddenGapPatterns.push(
    "endpoint activity",
    "collect endpoint activity",
    "endpoint telemetry"
  );
}


if (
  Array.isArray(
    assessment.remaining_gaps
  )
) {

  assessment.remaining_gaps.forEach(
    (gap, index) => {

      if (
        typeof gap !== "string"
      ) {
        return;
      }


      const normalized =
        gap.toLowerCase();


      const invalid =
        forbiddenGapPatterns.some(
          pattern =>
            normalized.trim() ===
            pattern.toLowerCase()
        );


      if (invalid) {

        errors.push(
          `remaining_gaps[${index}] duplicates evidence already collected successfully`
        );
      }
    }
  );
