      const normalized =
        action.toLowerCase();


      if (
        completedTools.has(
          "get_signins"
        ) &&
        normalized ===
          "collect historical sign-in data."
      ) {

        errors.push(
          `recommended_next_actions[${index}] repeats a completed investigation`
        );
      }


      if (
        completedTools.has(
          "get_endpoint_activity"
        ) &&
        normalized ===
          "collect endpoint activity."
      ) {

        errors.push(
          `recommended_next_actions[${index}] repeats a completed investigation`
        );
      }
    }
  );
}


// --------------------------------------------------
// 17. Reject invalid assessment
// --------------------------------------------------

if (
  errors.length > 0
) {

  throw new Error(
    `Evidence analysis validation failed: ${errors.join("; ")}`
  );
}


