// --------------------------------------------------
// 2. Extract current state
// --------------------------------------------------

const verdict =
  assessment.verdict;

const confidence =
  assessment.confidence;

const remainingGaps =
  Array.isArray(
    assessment.remaining_gaps
  )
    ? assessment.remaining_gaps
    : [];

const recommendedActions =
  Array.isArray(
    assessment.recommended_next_actions
  )
    ? assessment.recommended_next_actions
    : [];


// --------------------------------------------------
// 3. Iteration policy
// --------------------------------------------------
//
// Current policy:
//
// Continue investigation only when:
// - verdict is inconclusive or suspicious
// - relevant evidence gaps remain
//
// Do not automatically continue when:
// - verdict is malicious
// - verdict is benign
//
// Iteration limits will be enforced separately.
// --------------------------------------------------

let needsMoreInvestigation =
  false;

const reasons = [];


if (
  verdict === "inconclusive"
) {

  if (
    remainingGaps.length > 0
  ) {

    needsMoreInvestigation =
      true;

    reasons.push(
      "The current verdict is inconclusive and unresolved evidence gaps remain."
    );
  }
}


if (
  verdict === "suspicious"
) {

  if (
    remainingGaps.length > 0
  ) {

    needsMoreInvestigation =
      true;

    reasons.push(
      "The current verdict is suspicious and additional evidence may materially improve the assessment."
    );
  }
}


// --------------------------------------------------
// 4. Terminal verdicts
// --------------------------------------------------

if (
  verdict === "benign"
) {

  needsMoreInvestigation =
    false;

  reasons.push(
    "The current verdict is benign; no automatic investigation continuation is requested."
  );
}


if (
  verdict === "malicious"
) {

  needsMoreInvestigation =
    false;

  reasons.push(
    "The current verdict is malicious; the investigation should transition to response or escalation rather than automatic evidence collection."
  );
}


// --------------------------------------------------
// 5. No actionable gaps
// --------------------------------------------------

if (
  remainingGaps.length === 0
) {

  needsMoreInvestigation =
    false;

  reasons.push(
    "No remaining evidence gaps were identified."
  );
}


