  );
}


if (
  maxIterations < 1
) {
  throw new Error(
    "max_iterations must be greater than or equal to 1"
  );
}


// --------------------------------------------------
// 4. Determine whether another round is allowed
// --------------------------------------------------

const canContinue =
  currentIteration <=
    maxIterations;


