// --------------------------------------------------
// 5. Iterative evidence validation
// --------------------------------------------------

if (
  !Array.isArray(
    iterativeEvidence.tool_executions
  )
) {
  throw new Error(
    "Iterative investigation evidence does not contain tool_executions"
  );
}


// --------------------------------------------------
// 6. Combine executions
// --------------------------------------------------

const combinedExecutions = [

  ...initialEvidence.tool_executions,

  ...iterativeEvidence.tool_executions
];


// --------------------------------------------------
// 7. Recalculate execution summary
// --------------------------------------------------

let successfulTools = 0;
let partialTools = 0;
let failedTools = 0;
let rejectedTools = 0;
let totalEvidenceItems = 0;


for (
  const execution
  of combinedExecutions
) {

  if (
    execution.status === "success"
  ) {
    successfulTools++;
  }


  if (
    execution.status === "partial"
  ) {
    partialTools++;
  }


  if (
    execution.status === "error"
  ) {
    failedTools++;
  }


  if (
    execution.status === "rejected"
  ) {
    rejectedTools++;
  }


  if (
    Array.isArray(
      execution.evidence
    )
  ) {
    totalEvidenceItems +=
      execution.evidence.length;
  }
}


// --------------------------------------------------
// 8. Determine combined status
// --------------------------------------------------

let status =
  "success";


if (
  failedTools > 0 ||
  rejectedTools > 0
) {

  status =
    successfulTools > 0 ||
    partialTools > 0
      ? "partial"
      : "error";

} else if (
  partialTools > 0
) {

  status =
    "partial";
}


// --------------------------------------------------
// 9. Build combined canonical context
// --------------------------------------------------

return [
  {
    json: {

      context_version:
        "1.0",

      task:
        "iterative_evidence_based_investigation_assessment",

