// ==================================================
// Second Evidence Analysis Validator
//
// Validates a subsequent evidence-based assessment.
//
// Security properties:
// - exact evidence provenance
// - exact field/value/type matching
// - authoritative remaining-gap preservation
// - recommended-action to gap binding
// - no unauthorized investigation creation
//
// The LLM output is treated as untrusted input.
// ==================================================


// --------------------------------------------------
// 1. Extract Ollama response
// --------------------------------------------------

const response =
  $json;

