  response?.message?.content;


if (
  !content ||
  typeof content !== "string"
) {
  throw new Error(
    "Second evidence analysis validation failed: message.content is missing or empty"
  );
}


// --------------------------------------------------
// 2. Parse JSON
// --------------------------------------------------

let assessment;

try {

  assessment =
    JSON.parse(content);

} catch (error) {

  throw new Error(
    `Second evidence analysis validation failed: response is not valid JSON: ${error.message}`
  );
}


// --------------------------------------------------
// 3. Retrieve authoritative context
// --------------------------------------------------

const context =
  $("Combined Investigation Evidence Builder")
    .first()
    .json;


if (
  !context ||
  typeof context !== "object" ||
  Array.isArray(context)
) {
  throw new Error(
    "Second evidence analysis validation failed: combined investigation context is unavailable"
  );
}


// --------------------------------------------------
// 4. Validation state
// --------------------------------------------------

const errors = [];


// --------------------------------------------------
// 5. Helpers
// --------------------------------------------------

function requireString(
  field,
  value
) {

  if (
    typeof value !== "string" ||
    value.trim() === ""
  ) {

    errors.push(
      `${field} must be a non-empty string`
    );
  }
}


function validateStringArray(
  field,
  value
) {

  if (
    !Array.isArray(value)
  ) {

    errors.push(
      `${field} must be an array`
    );

    return;
  }


  value.forEach(
    (item, index) => {

      if (
        typeof item !== "string" ||
        item.trim() === ""
      ) {

        errors.push(
          `${field}[${index}] must be a non-empty string`
        );
      }
    }
  );
}


function deepEqual(
  valueA,
  valueB
) {

  if (
    valueA === valueB
  ) {
    return true;
  }


  if (
    valueA === null ||
    valueB === null ||
    valueA === undefined ||
    valueB === undefined
  ) {
    return false;
  }


  if (
    typeof valueA !==
      typeof valueB
  ) {
    return false;
  }


  if (
    Array.isArray(valueA) ||
    Array.isArray(valueB)
  ) {

    if (
      !Array.isArray(valueA) ||
      !Array.isArray(valueB)
    ) {
      return false;
    }


    if (
      valueA.length !==
        valueB.length
    ) {
      return false;
    }


    for (
      let index = 0;
      index < valueA.length;
      index++
    ) {

      if (
        !deepEqual(
          valueA[index],
          valueB[index]
        )
      ) {
        return false;
      }
    }


    return true;
  }


  if (
    typeof valueA === "object"
  ) {

    const keysA =
      Object.keys(valueA)
        .sort();

    const keysB =
      Object.keys(valueB)
        .sort();


    if (
      keysA.length !==
        keysB.length
    ) {
      return false;
    }


    for (
      let index = 0;
      index < keysA.length;
      index++
    ) {

      if (
        keysA[index] !==
          keysB[index]
      ) {
        return false;
      }
    }


    for (
      const key
      of keysA
    ) {

      if (
        !deepEqual(
          valueA[key],
          valueB[key]
        )
      ) {
        return false;
      }
    }


    return true;
  }


  return false;
}


// --------------------------------------------------
// 6. Evidence index
// --------------------------------------------------

const evidenceIndex =
  new Map();

const validToolSources =
  new Set();


function addEvidence(
  source,
  field,
  value
) {

  const key =
    `${source}::${field}`;


  if (
    !evidenceIndex.has(key)
  ) {

    evidenceIndex.set(
      key,
      []
    );
  }


  evidenceIndex
    .get(key)
    .push(value);
}


function flattenEvidence(
  source,
  value,
  prefix = ""
) {

  if (
    value === null ||
    value === undefined
  ) {

    if (prefix) {
      addEvidence(
        source,
        prefix,
        value
      );
    }

    return;
  }


  if (
    Array.isArray(value)
  ) {

    if (prefix) {
      addEvidence(
        source,
        prefix,
        value
      );
    }

    return;
  }


  if (
    typeof value === "object"
  ) {

    if (prefix) {
      addEvidence(
        source,
        prefix,
        value
      );
    }


    for (
      const [key, childValue]
      of Object.entries(value)
    ) {

      const childPrefix =
        prefix
          ? `${prefix}.${key}`
          : key;


      flattenEvidence(
        source,
        childValue,
        childPrefix
      );
    }

    return;
  }


  if (prefix) {

    addEvidence(
      source,
      prefix,
      value
    );
  }
}


// --------------------------------------------------
// 7. Index combined tool evidence
// --------------------------------------------------

const toolExecutions =
