  if (
    Array.isArray(valueA) ||
    Array.isArray(valueB)
  ) {

    if (
      !Array.isArray(valueA) ||
      !Array.isArray(valueB)
    ) {
      return false;
    }


    if (
      valueA.length !==
        valueB.length
    ) {
      return false;
    }


    for (
      let index = 0;
      index < valueA.length;
      index++
    ) {

      if (
        !deepEqual(
          valueA[index],
          valueB[index]
        )
      ) {
        return false;
      }
    }


    return true;
  }


  if (
    typeof valueA === "object"
