    const keysA =
      Object.keys(valueA)
        .sort();

    const keysB =
      Object.keys(valueB)
        .sort();


    if (
      keysA.length !==
        keysB.length
    ) {
      return false;
    }


    for (
      let index = 0;
      index < keysA.length;
      index++
    ) {

      if (
        keysA[index] !==
          keysB[index]
      ) {
        return false;
      }
    }


    for (
      const key
      of keysA
    ) {

      if (
        !deepEqual(
          valueA[key],
          valueB[key]
        )
      ) {
        return false;
      }
    }


    return true;
  }


  return false;
