) {

  const returnedGapSet =
    new Set(
      assessment.remaining_gaps
        .filter(
          gap =>
            typeof gap === "string"
        )
        .map(
          gap =>
            gap.trim()
        )
    );


  // No authoritative gap may disappear.

  for (
    const gap
    of authoritativeRemainingGaps
  ) {

    if (
      !returnedGapSet.has(gap)
    ) {

      errors.push(
        `authoritative unresolved gap disappeared from the assessment: '${gap}'`
      );
    }
  }


  // No new gap may appear.

  for (
    const gap
    of returnedGapSet
  ) {

    if (
      !authoritativeGapSet.has(gap)
    ) {

      errors.push(
        `remaining_gaps contains a gap not authorized by the combined investigation context: '${gap}'`
      );
    }
  }
}


// --------------------------------------------------
// 15. Recommended action validation
// --------------------------------------------------

if (
  Array.isArray(
    assessment.recommended_next_actions
  )
) {

  assessment.recommended_next_actions.forEach(
    (item, index) => {

      const prefix =
        `recommended_next_actions[${index}]`;


      if (
        !item ||
        typeof item !== "object" ||
        Array.isArray(item)
      ) {

        errors.push(
          `${prefix} must be an object containing action and addresses_gap`
        );

        return;
      }


      const keys =
        Object.keys(item)
          .sort();


      const expectedKeys =
        [
          "action",
          "addresses_gap"
        ]
          .sort();


      if (
        keys.length !==
          expectedKeys.length ||
        keys.some(
          (key, keyIndex) =>
            key !==
              expectedKeys[keyIndex]
        )
      ) {

        errors.push(
          `${prefix} must contain exactly the fields 'action' and 'addresses_gap'`
        );
      }


      requireString(
        `${prefix}.action`,
        item.action
      );


      requireString(
        `${prefix}.addresses_gap`,
        item.addresses_gap
      );


      if (
        typeof item.addresses_gap === "string"
      ) {

        const gap =
          item.addresses_gap.trim();


        if (
          !authoritativeGapSet.has(gap)
        ) {

          errors.push(
            `${prefix}.addresses_gap does not reference an authoritative remaining gap: '${gap}'`
          );
        }


        if (
          Array.isArray(
            assessment.remaining_gaps
          ) &&
          !assessment.remaining_gaps.includes(
            gap
          )
        ) {

          errors.push(
            `${prefix}.addresses_gap does not reference a gap present in remaining_gaps`
          );
        }
      }
    }
  );
}


// --------------------------------------------------
// 16. Reject invalid assessment
// --------------------------------------------------

return [
  {
    json: {

      valid:
        errors.length === 0,

      errors,

      assessment:
        errors.length === 0
          ? assessment
          : null,

      raw_assessment:
        assessment
    }
  }
];

