// --------------------------------------------------

const userPrompt =
  "Repair the invalid iterative investigation plan. " +

  "VALIDATOR ERRORS: " +
  JSON.stringify(validation.errors) +
  ". " +

  "INVALID PLAN: " +
  JSON.stringify(validation.raw_plan) +
  ". " +

  "AUTHORITATIVE ITERATIVE CONTEXT: " +
  JSON.stringify(context) +
  ". " +

  "AUTHORITATIVE REMAINING GAPS: " +
  JSON.stringify(authoritativeGaps) +
  ". " +

  "Return exactly one JSON object matching this structure: " +
  JSON.stringify(expectedOutput) +
  ". " +

  "MANDATORY RULES: " +

  "1. plan_version must be exactly '1.0'. " +

  "2. alert_id must exactly match the authoritative context. " +

  "3. iteration_number must exactly match the authoritative context. " +

  "4. investigation_steps must contain only executable steps justified by an authoritative remaining gap. " +

  "5. addresses_gap must exactly match one of the authoritative remaining gaps, character for character. " +

  "6. unresolved_gaps[].gap must exactly match one of the authoritative remaining gaps. " +

  "7. No authoritative gap may disappear. " +

  "8. Do not add any gap that is absent from AUTHORITATIVE REMAINING GAPS. " +

  "9. Do not create a new gap for destination IP 20.190.128.25. " +

  "10. Do not investigate 20.190.128.25 unless an authoritative remaining gap explicitly authorizes reputation analysis for that IP. " +

  "11. Do not create a gap about PowerShell intent, PowerShell purpose, command intent, or command clarification unless that exact gap exists in AUTHORITATIVE REMAINING GAPS. " +

  "12. get_ip_reputation may only be used when addresses_gap is explicitly an IP-reputation gap. " +

  "13. get_ip_reputation may target only IPs already present in authoritative evidence. " +

  "14. Do not repeat get_signins for john.doe@example.com with exactly the same parameters already used. " +

  "15. Additional sign-in history requires an explicit new investigation scope or time_range. Never invent one. If none exists, keep that gap unresolved. " +

  "16. Do not repeat get_endpoint_activity for WIN11-LAPTOP-01 with exactly the same parameters already used. " +

  "17. No currently available tool authoritatively verifies device ownership. A device-ownership gap must remain unresolved unless an appropriate capability exists in the authoritative context. " +

  "18. Allowed tools are get_signins, get_ip_reputation and get_endpoint_activity only. " +

  "19. Step IDs must be sequential: step-1, step-2, step-3, etc. " +

  "20. Return only the repaired JSON object.";


// --------------------------------------------------
// 7. Ollama request
// --------------------------------------------------

return [
  {
    json: {

      model:
        "qwen3:8b",

      messages: [
        {
          role:
            "system",

          content:
            systemPrompt
        },

        {
          role:
            "user",

          content:
            userPrompt
        }
      ],

      stream:
        false,

      think:
        false,

      keep_alive:
        "5m",

      format:
        "json"
    }
  }
];

// ==================================================
// Iterative Plan Validator
//
// Validates a subsequent investigation plan.
//
// Security properties:
// - exact alert_id / iteration matching
// - tool allowlist
// - parameter allowlist
// - entity provenance
// - no duplicate completed queries
// - exact remaining-gap coverage
// - no invented gaps
// - sequential step IDs
//
// LLM output is treated as untrusted input.
//
// IMPORTANT:
// Validation failures are returned as an envelope
// instead of throwing so one controlled repair
// attempt can be performed.
// ==================================================


// --------------------------------------------------
// 1. Extract Ollama response
// --------------------------------------------------

const response = $json;

const content =
  response?.message?.content;


// --------------------------------------------------
// 2. Validation state
// --------------------------------------------------

const errors = [];

let plan = null;


// --------------------------------------------------
// 3. Parse LLM output
// --------------------------------------------------

if (
  !content ||
  typeof content !== "string"
) {

  errors.push(
    "message.content is missing or empty"
  );

} else {

  try {

    plan =
      JSON.parse(content);

  } catch (error) {

    errors.push(
      `response is not valid JSON: ${error.message}`
    );
  }
}


// --------------------------------------------------
// 4. Retrieve authoritative iterative context
// --------------------------------------------------

const context =
  $("Second Investigation Planning Input")
    .first()
    .json;


if (
  !context ||
  typeof context !== "object" ||
  Array.isArray(context)
) {

  throw new Error(
    "Iterative plan validation failed: iterative planning context is unavailable"
  );
}


// --------------------------------------------------
// 5. Helpers
// --------------------------------------------------

function requireString(
  field,
  value
) {

  if (
    typeof value !== "string" ||
    value.trim() === ""
  ) {

    errors.push(
      `${field} must be a non-empty string`
    );
  }
}


function normalizedString(
  value
) {

  return typeof value === "string"
    ? value.trim()
    : "";
}


function deepEqual(
  a,
  b
) {

  return (
    JSON.stringify(a) ===
    JSON.stringify(b)
  );
}


// --------------------------------------------------
// 6. Authoritative remaining gaps
// --------------------------------------------------

const authoritativeGaps =
  Array.isArray(
    context.remaining_gaps
  )
    ? context.remaining_gaps
        .filter(
          gap =>
            typeof gap === "string" &&
            gap.trim() !== ""
        )
        .map(
          gap =>
            gap.trim()
        )
    : [];


const authoritativeGapSet =
  new Set(
    authoritativeGaps
  );


// --------------------------------------------------
// 7. Authoritative observed entities
// --------------------------------------------------

const allowedIps =
  new Set();

const allowedUsers =
  new Set();

const allowedHosts =
  new Set();


const previousObservedEvidence =
  context
    ?.previous_assessment
    ?.observed_evidence || [];


for (
  const evidence
  of previousObservedEvidence
) {

  if (
    !evidence ||
    typeof evidence !== "object"
  ) {
    continue;
  }


  const field =
    evidence.field;

  const value =
    evidence.value;


  const values =
    Array.isArray(value)
      ? value
      : [value];


  for (
    const item
    of values
  ) {

    if (
      item === null ||
      item === undefined
    ) {
      continue;
    }


    const normalized =
      String(item).trim();


    if (!normalized) {
      continue;
    }


    if (
      field === "source_ip" ||
      field === "destination_ip" ||
      field === "network.destination_ip"
    ) {

      allowedIps.add(
        normalized
      );
    }


    if (
      field === "user" ||
      field === "users"
    ) {

      allowedUsers.add(
        normalized
      );
    }


    if (
      field === "host" ||
      field === "hosts"
    ) {

      allowedHosts.add(
        normalized
      );
    }
  }
}


// --------------------------------------------------
// 8. Add entities explicitly known from case
// --------------------------------------------------

allowedIps.add(
  "185.220.101.20"
);

allowedIps.add(
  "91.198.174.20"
);

allowedUsers.add(
  "john.doe@example.com"
);

allowedHosts.add(
  "WIN11-LAPTOP-01"
);


// --------------------------------------------------
// 9. Completed investigation queries
// --------------------------------------------------

const completedInvestigations = [

  {
    tool:
      "get_signins",

    parameters: {
      user:
        "john.doe@example.com"
    }
  },

  {
    tool:
      "get_endpoint_activity",

    parameters: {
      host:
        "WIN11-LAPTOP-01"
    }
  }

];


// --------------------------------------------------
// 10. Tool policies
// --------------------------------------------------

const toolPolicies = {

  get_signins: {

    requiredParameters: [
      "user"
    ],

    allowedParameters: [
      "user",
      "time_range",
      "limit"
    ],

    entityParameter:
      "user",

    allowedEntities:
      allowedUsers
  },


  get_ip_reputation: {

    requiredParameters: [
      "ip"
    ],

    allowedParameters: [
      "ip"
    ],

    entityParameter:
      "ip",

    allowedEntities:
      allowedIps
  },


  get_endpoint_activity: {

    requiredParameters: [
      "host"
    ],

    allowedParameters: [
      "host",
      "time_range",
      "limit"
    ],

    entityParameter:
      "host",

    allowedEntities:
      allowedHosts
  }

};


// --------------------------------------------------
// 11. Top-level structure
// --------------------------------------------------

if (
  plan === null
) {

  // Parsing/input errors are already present.

} else if (
  !plan ||
  typeof plan !== "object" ||
  Array.isArray(plan)
) {

  errors.push(
    "plan must be a JSON object"
  );

} else {

  if (
    plan.plan_version !== "1.0"
  ) {

    errors.push(
      "plan_version must be '1.0'"
    );
  }


  requireString(
    "alert_id",
    plan.alert_id
  );


  if (
    plan.alert_id !==
      context.alert_id
  ) {

    errors.push(
      "alert_id does not match the iterative planning context"
    );
  }


  if (
    plan.iteration_number !==
      context.iteration_number
  ) {

    errors.push(
      "iteration_number does not match the iterative planning context"
    );
  }


  requireString(
    "objective",
    plan.objective
  );


  if (
    !Array.isArray(
      plan.investigation_steps
    )
  ) {

    errors.push(
      "investigation_steps must be an array"
    );
  }


  if (
    !Array.isArray(
      plan.unresolved_gaps
    )
  ) {

    errors.push(
      "unresolved_gaps must be an array"
    );
  }
}


// --------------------------------------------------
// 12. Track gap coverage
// --------------------------------------------------

const coveredGaps =
  new Map();


for (
  const gap
  of authoritativeGaps
) {

  coveredGaps.set(
    gap,
    0
  );
}


// --------------------------------------------------
// 13. Validate investigation steps
// --------------------------------------------------

const validPriorities = [
  "high",
  "medium",
  "low"
];


if (
  plan &&
  Array.isArray(
    plan.investigation_steps
  )
) {

  plan.investigation_steps.forEach(
    (step, index) => {

      const prefix =
        `investigation_steps[${index}]`;


      if (
        !step ||
        typeof step !== "object" ||
        Array.isArray(step)
      ) {

        errors.push(
          `${prefix} must be an object`
        );

        return;
      }


      const expectedStepId =
        `step-${index + 1}`;


      if (
        step.step_id !==
          expectedStepId
      ) {

        errors.push(
          `${prefix}.step_id must be '${expectedStepId}'`
        );
      }


      if (
        !validPriorities.includes(
          step.priority
        )
      ) {

        errors.push(
          `${prefix}.priority contains an invalid value`
        );
      }


      requireString(
        `${prefix}.purpose`,
        step.purpose
      );


      requireString(
        `${prefix}.evidence_target`,
        step.evidence_target
      );


      requireString(
        `${prefix}.addresses_gap`,
        step.addresses_gap
      );


      if (
        typeof step.addresses_gap === "string"
      ) {

        const gap =
          step.addresses_gap.trim();


        if (
          !authoritativeGapSet.has(
            gap
          )
        ) {

          errors.push(
            `${prefix}.addresses_gap does not match any supplied remaining gap: '${gap}'`
          );

        } else {

          coveredGaps.set(
            gap,
            (
              coveredGaps.get(gap) ||
              0
            ) + 1
          );
        }
      }


      if (
        typeof step.tool !== "string" ||
        !Object.prototype.hasOwnProperty.call(
          toolPolicies,
          step.tool
        )
      ) {

        errors.push(
          `${prefix}.tool '${step.tool}' is not allowed`
        );

        return;
      }


      const policy =
        toolPolicies[
          step.tool
        ];


      if (
        !step.parameters ||
        typeof step.parameters !== "object" ||
        Array.isArray(step.parameters)
      ) {

        errors.push(
          `${prefix}.parameters must be an object`
        );

        return;
      }


      for (
        const parameter
        of policy.requiredParameters
      ) {

        if (
          !Object.prototype.hasOwnProperty.call(
            step.parameters,
            parameter
          )
        ) {

          errors.push(
            `${prefix}.parameters.${parameter} is required for ${step.tool}`
          );
        }
      }


      for (
        const parameter
        of Object.keys(
          step.parameters
        )
      ) {

        if (
          !policy.allowedParameters.includes(
            parameter
          )
        ) {

          errors.push(
            `${prefix}.parameters.${parameter} is not allowed for ${step.tool}`
          );
        }
      }


      const entityValue =
        step.parameters[
          policy.entityParameter
        ];


      if (
        typeof entityValue !== "string" ||
        entityValue.trim() === ""
      ) {

        errors.push(
          `${prefix}.parameters.${policy.entityParameter} must be a non-empty string`
        );

      } else if (
        !policy.allowedEntities.has(
          entityValue
        )
      ) {

        errors.push(
          `${prefix}.parameters.${policy.entityParameter} contains an entity not present in authoritative evidence: ${entityValue}`
        );
      }


      const duplicated =
        completedInvestigations.some(
          completed =>
            completed.tool ===
              step.tool &&
            deepEqual(
              completed.parameters,
              step.parameters
            )
        );


      if (duplicated) {

        errors.push(
          `${prefix} repeats an investigation that already completed successfully`
        );
      }
    }
  );
}


// --------------------------------------------------
// 14. Validate unresolved gaps
// --------------------------------------------------

const seenUnresolvedGaps =
  new Set();


if (
  plan &&
  Array.isArray(
    plan.unresolved_gaps
  )
) {

  plan.unresolved_gaps.forEach(
    (item, index) => {

      const prefix =
        `unresolved_gaps[${index}]`;


      if (
        !item ||
        typeof item !== "object" ||
        Array.isArray(item)
      ) {

        errors.push(
          `${prefix} must be an object`
        );

        return;
      }


      requireString(
        `${prefix}.gap`,
        item.gap
      );


      requireString(
        `${prefix}.reason`,
        item.reason
      );


      if (
        typeof item.gap === "string"
      ) {

        const gap =
          item.gap.trim();


        if (
          !authoritativeGapSet.has(
            gap
          )
        ) {

          errors.push(
            `${prefix}.gap was not present in the supplied remaining gaps: '${gap}'`
          );

          return;
        }


        if (
          seenUnresolvedGaps.has(
            gap
          )
        ) {

          errors.push(
            `${prefix}.gap is duplicated`
          );

          return;
        }


        seenUnresolvedGaps.add(
          gap
        );


        coveredGaps.set(
          gap,
          (
            coveredGaps.get(gap) ||
            0
          ) + 1
        );
      }
    }
  );
}


// --------------------------------------------------
// 15. Exact gap coverage
// --------------------------------------------------

for (
  const gap
  of authoritativeGaps
) {

  const count =
    coveredGaps.get(gap) || 0;


  if (
    count === 0
  ) {

    errors.push(
      `remaining gap is not accounted for by investigation_steps or unresolved_gaps: '${gap}'`
    );
  }
}


// --------------------------------------------------
// 16. Reject unjustified IP reputation use
// --------------------------------------------------

if (
  plan &&
  Array.isArray(
    plan.investigation_steps
  )
) {

  plan.investigation_steps.forEach(
    (step, index) => {

      if (
        step?.tool !==
          "get_ip_reputation"
      ) {
        return;
      }


      const addressesGap =
        normalizedString(
          step.addresses_gap
        );


      if (
        !authoritativeGapSet.has(
          addressesGap
        )
      ) {
        return;
      }


      const normalizedGap =
        addressesGap.toLowerCase();


      if (
        !normalizedGap.includes(
          "ip reputation"
        )
      ) {

        errors.push(
          `investigation_steps[${index}]: get_ip_reputation is not justified by the referenced gap`
        );
      }
    }
  );
}


// --------------------------------------------------
// 17. Return validation envelope
// --------------------------------------------------

return [
  {
    json: {

      valid:
        errors.length === 0,

      errors,

      plan:
        errors.length === 0
          ? plan
          : null,

      raw_plan:
        plan,

      authoritative_gaps:
        authoritativeGaps
    }
  }
];

// ==================================================
// Iterative Plan Repair Failed
//
// Terminal controlled failure after one unsuccessful
// iterative-plan repair attempt.
// ==================================================

const validation =
  $json;


if (
  !validation ||
  typeof validation !== "object" ||
  validation.valid !== false
) {

  throw new Error(
    "Iterative Plan Repair Failed requires an invalid repaired-plan validation result"
  );
}


return [
  {
    json: {

      investigation_control_version:
        "1.0",

      status:
        "stopped",

      reason:
        "iterative_plan_repair_failed",

      errors:
        Array.isArray(validation.errors)
          ? validation.errors
          : [],

      raw_plan:
        validation.raw_plan ?? null
    }
  }
];

// ==================================================
// Valid Iterative Plan
//
// Extracts the canonical validated iterative plan
// from the validation envelope.
// ==================================================

const validation =
  $json;


if (
  !validation ||
  typeof validation !== "object" ||
  Array.isArray(validation)
) {

  throw new Error(
    "Valid Iterative Plan requires a validation envelope"
  );
}


if (
  validation.valid !== true
) {

  throw new Error(
    "Valid Iterative Plan received an invalid plan"
  );
}


if (
  !validation.plan ||
  typeof validation.plan !== "object" ||
  Array.isArray(validation.plan)
) {

  throw new Error(
    "Valid Iterative Plan requires a canonical plan"
  );
}


return [
  {
    json:
      validation.plan
  }
];

// ==================================================
// No Executable Iterative Steps
//
// Handles a valid iterative plan where all
// authoritative gaps remain unresolved and there are
// no executable investigation steps.
//
// This is not an error condition.
// ==================================================

const plan = $json;

if (
  !plan ||
  typeof plan !== "object" ||
  Array.isArray(plan)
) {
  throw new Error(
    "No Executable Iterative Steps requires a valid iterative plan"
  );
}

if (
  !Array.isArray(plan.investigation_steps)
) {
  throw new Error(
    "No Executable Iterative Steps requires investigation_steps"
  );
}

if (
  plan.investigation_steps.length !== 0
) {
  throw new Error(
    "No Executable Iterative Steps received a plan containing executable steps"
  );
}

if (
  !Array.isArray(plan.unresolved_gaps)
) {
  throw new Error(
    "No Executable Iterative Steps requires unresolved_gaps"
  );
}

return [
  {
    json: {
      iterative_execution_version: "1.0",
      alert_id: plan.alert_id,
      iteration_number: plan.iteration_number,
      status: "no_executable_steps",
      decision: "finalize",
      termination_reason: "no_executable_remaining_gaps",
      unresolved_gaps: plan.unresolved_gaps,
      plan
    }
  }
];

// ==================================================
// Final Investigation Result - No Executable Steps
//
// Produces a canonical terminal investigation result
// when an iterative plan is valid but contains no
// executable investigation steps.
//
// No new evidence was collected, therefore the
// previous validated assessment remains authoritative.
// ==================================================

const input = $json;


// --------------------------------------------------
// 1. Validate iterative execution state
// --------------------------------------------------

if (
  !input ||
  typeof input !== "object" ||
  Array.isArray(input)
) {
  throw new Error(
    "Final Investigation Result - No Executable Steps requires an execution state"
  );
}


if (
  input.iterative_execution_version !== "1.0"
) {
  throw new Error(
    "iterative_execution_version must be '1.0'"
  );
}


if (
  input.status !== "no_executable_steps"
) {
  throw new Error(
    "Final Investigation Result - No Executable Steps requires status 'no_executable_steps'"
  );
}


if (
  input.decision !== "finalize"
) {
  throw new Error(
    "Final Investigation Result - No Executable Steps requires decision 'finalize'"
  );
}


if (
  input.termination_reason !==
    "no_executable_remaining_gaps"
) {
  throw new Error(
    "Unexpected termination_reason"
  );
}


if (
  typeof input.alert_id !== "string" ||
  input.alert_id.trim() === ""
) {
  throw new Error(
    "alert_id is required"
  );
}


if (
  !Array.isArray(
    input.unresolved_gaps
  )
) {
  throw new Error(
    "unresolved_gaps must be an array"
  );
}


// --------------------------------------------------
// 2. Retrieve authoritative previous assessment
// --------------------------------------------------
//
// No new tool evidence was collected in this branch,
// therefore we MUST NOT create a new assessment.
//
// The previous validated assessment remains the
// authoritative incident assessment.
// --------------------------------------------------

const planningContext =
  $("Second Investigation Planning Input")
    .first()
    .json;


if (
  !planningContext ||
  typeof planningContext !== "object" ||
  Array.isArray(planningContext)
) {
  throw new Error(
    "Could not retrieve Second Investigation Planning Input"
  );
}


const assessment =
  planningContext.previous_assessment;


if (
  !assessment ||
  typeof assessment !== "object" ||
  Array.isArray(assessment)
) {
  throw new Error(
    "Previous validated assessment is unavailable"
  );
}


if (
  assessment.alert_id !==
    input.alert_id
) {
  throw new Error(
    "alert_id mismatch between iterative execution and previous assessment"
  );
}


// --------------------------------------------------
// 3. Normalize unresolved gaps
// --------------------------------------------------

const unresolvedEvidenceRequirements =
  input.unresolved_gaps.map(
    (item, index) => {

      if (
        !item ||
        typeof item !== "object" ||
        Array.isArray(item)
      ) {
        throw new Error(
          `unresolved_gaps[${index}] must be an object`
        );
      }


      if (
        typeof item.gap !== "string" ||
        item.gap.trim() === ""
      ) {
        throw new Error(
          `unresolved_gaps[${index}].gap must be a non-empty string`
        );
      }


      if (
        typeof item.reason !== "string" ||
        item.reason.trim() === ""
      ) {
        throw new Error(
          `unresolved_gaps[${index}].reason must be a non-empty string`
        );
      }


      return {

        gap:
          item.gap.trim(),

        executable:
          false,

        tool:
          null,

        reason:
          item.reason.trim(),

        missing_requirements: [
          "supported_authorized_investigation_capability"
        ],

        recommended_action:
          "Obtain or implement an authoritative investigation capability capable of addressing this unresolved gap."
      };
    }
  );


// --------------------------------------------------
// 4. Build canonical final result
// --------------------------------------------------

const finalResult = {

  investigation_result_version:
    "1.0",

  alert_id:
    input.alert_id,

  status:
    "completed_with_unresolved_gaps",

  termination_reason:
    "no_executable_remaining_gaps",

  iteration_number:
    input.iteration_number ?? null,

  verdict:
    assessment.verdict,

  confidence:
    assessment.confidence,

  risk_assessment:
    assessment.risk_assessment,

  summary:
    assessment.summary,

  observed_evidence:
    Array.isArray(
      assessment.observed_evidence
    )
      ? assessment.observed_evidence
      : [],

  correlations:
    Array.isArray(
      assessment.correlations
    )
      ? assessment.correlations
      : [],

  hypotheses:
    Array.isArray(
      assessment.hypotheses
    )
      ? assessment.hypotheses
      : [],

  remaining_gaps:
    unresolvedEvidenceRequirements.map(
      item =>
        item.gap
    ),

  unresolved_evidence_requirements:
    unresolvedEvidenceRequirements,

  execution_summary: {

    remaining_gap_count:
      unresolvedEvidenceRequirements.length,

    executable_gap_count:
      0,

    non_executable_gap_count:
      unresolvedEvidenceRequirements.length,

    automated_investigation_complete:
      true,

    additional_tool_executions:
      0,

    additional_evidence_items:
      0
  }
};


// --------------------------------------------------
// 5. Return final result
// --------------------------------------------------

return [
  {
    json:
      finalResult
  }
];
